    var
        "Key": Text;
        ExpectedValue: Text;
        ActualValue: Text;
    begin
        if Expected.Count() <> Actual.Count() then
            Error(DictionaryDifferentSizeErr, Expected.Count(), Actual.Count());
        foreach "Key" in Expected.Keys() do begin
            if not Actual.Get("Key", ActualValue) then
                Error(MissingKeyErr, "Key");
